import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import { describe, expect, it } from 'vitest';

// Smoke test for the favicon / OG / PWA asset set generated by
// scripts/build-brand-assets.mjs. The assets are checked into the repo, not
// built at CI time, so a missing file means someone removed an asset without
// updating the script — which would silently break browser and OS branding
// and link previews. `--check` in CI catches the opposite: an asset edited by
// hand into something the script no longer reproduces.

const repoRoot = join(__dirname, '..', '..', '..');
const publicDir = join(repoRoot, 'apps', 'web', 'public');
const indexHtmlPath = join(repoRoot, 'apps', 'web', 'index.html');

describe('brand assets', () => {
  const expectedAssets = [
    'favicon.svg',
    'favicon.ico',
    'favicon-32.png',
    'apple-touch-icon.png',
    'icon-192.png',
    'icon-512.png',
    'icon-192-maskable.png',
    'icon-512-maskable.png',
    'og-image.png',
    'site.webmanifest',
  ];

  it.each(expectedAssets)('apps/web/public/%s exists', (name) => {
    expect(existsSync(join(publicDir, name))).toBe(true);
  });

  it('index.html links the favicons, apple-touch-icon, manifest, and OG card', () => {
    const html = readFileSync(indexHtmlPath, 'utf8');
    // The PWA icon-* PNGs are referenced from site.webmanifest,
    // not from <head>; everything else needs to be in the HTML.
    const htmlAssets = [
      'favicon.svg',
      'favicon.ico',
      'favicon-32.png',
      'apple-touch-icon.png',
      'site.webmanifest',
      'og-image.png',
    ];
    for (const name of htmlAssets) {
      expect(html).toContain(`/${name}`);
    }
    // Scrapers prefer explicit dimensions on og:image so they
    // don't need to fetch the bytes to lay out the card.
    expect(html).toMatch(/og:image:width.*1200/);
    expect(html).toMatch(/og:image:height.*630/);
    expect(html).toContain('apple-touch-icon');
    expect(html).toContain('manifest');
  });

  it('site.webmanifest declares all four PWA icon variants', () => {
    const manifest = JSON.parse(readFileSync(join(publicDir, 'site.webmanifest'), 'utf8')) as {
      icons: Array<{ src: string; sizes: string; purpose: string }>;
    };
    const purposes = manifest.icons.map((i) => `${i.sizes} ${i.purpose}`).sort();
    expect(purposes).toEqual([
      '192x192 any',
      '192x192 maskable',
      '512x512 any',
      '512x512 maskable',
    ]);
  });
});
